      rolloutInference.hashCode ^
      rolloutPercent.hashCode ^
      copyTo.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UploadSpecView &&
          runtimeType == other.runtimeType &&
          path == other.path &&
          peer == other.peer &&
          name == other.name &&
